function fatalBoot(message, detail="") {
  console.error("Nolan Electric boot error:", message, detail);
  root.innerHTML=`<div class="boot-state"><div class="card boot-card"><div class="brand">Nolan Electric</div><div class="eyebrow">JOB COMMAND CENTER</div><h2>App could not start</h2><p>${esc(message)}</p><p class="sub">${esc(detail)}</p><button class="btn primary" onclick="location.reload()">Reload App</button></div></div>`;
}
window.addEventListener("error",e=>{console.error("Nolan Electric runtime error:",e.error||e.message); if(document.querySelector(".app-shell")) toast("Something went wrong. The app is still open — try that action again.","error"); else fatalBoot("A JavaScript error stopped the app.",e.error?.message||e.message||"Check the browser console.");});
window.addEventListener("unhandledrejection",e=>{console.error("Nolan Electric background error:",e.reason); if(document.querySelector(".app-shell")) toast("A background operation failed. Please try again.","error"); else fatalBoot("A background operation failed.",e.reason?.message||String(e.reason||"Unknown error"));});
