function urlForPush(jobId){return new URL(jobId?`?job=${encodeURIComponent(jobId)}`:'',location.href).href}
function base64ToUint8Array(base64){const pad='='.repeat((4-base64.length%4)%4),raw=atob((base64+pad).replace(/-/g,'+').replace(/_/g,'/'));return Uint8Array.from([...raw].map(c=>c.charCodeAt(0)))}
async function registerPushServiceWorker(){
 if(!('serviceWorker' in navigator)||!('PushManager' in window)||!('Notification' in window))return null;
 try{pushRegistration=await navigator.serviceWorker.register('./sw-v86.js',{scope:'./'});await navigator.serviceWorker.ready;return pushRegistration}catch(err){console.warn('Push setup unavailable:',err);return null}
}
async function claimPushSubscription(sub=null){
 if(!session?.user?.id) return {ok:false,error:'Not signed in'};
 try{
  const current=sub||await getPushSubscription();
  if(!current) return {ok:false,skipped:true,error:'No browser push subscription'};
  const j=current.toJSON();
  const r=await sb.functions.invoke('claim-push',{body:{endpoint:j.endpoint,p256dh:j.keys?.p256dh||'',auth:j.keys?.auth||'',user_agent:navigator.userAgent}});
  if(r.error||r.data?.error) throw new Error(r.error?.message||r.data?.error||'Could not claim push subscription');
  return r.data||{ok:true};
 }catch(err){console.warn('Push subscription sync failed:',err);return {ok:false,error:err?.message||String(err)}}
}
async function getPushSubscription(){try{return (await navigator.serviceWorker.ready).pushManager.getSubscription()}catch(_){return null}}
async function enablePushNotifications(){
 if(!session?.user?.id){toast('Sign in first.');return false}
 const reg=pushRegistration||await registerPushServiceWorker();
 if(!reg){toast('Push notifications are not supported by this browser.');return false}
 const publicKey=await loadVapidPublicKey();
 if(!publicKey){toast('Push service is not configured.');return false}
 const permission=await Notification.requestPermission();
 if(permission!=='granted'){toast('Notification permission was not granted.');return false}
 try{
  let sub=await reg.pushManager.getSubscription();
  // Force a fresh subscription so the browser subscription is guaranteed to use the current VAPID key.
  // This is required after rotating VAPID keys during development.
  if(sub){try{await sub.unsubscribe();}catch(_){} sub=null;}
  sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:base64ToUint8Array(publicKey)});
  const j=sub.toJSON();
  const payload={profile_id:session.user.id,endpoint:j.endpoint,p256dh:j.keys?.p256dh||'',auth:j.keys?.auth||'',user_agent:navigator.userAgent,updated_at:new Date().toISOString()};
  const claim=await claimPushSubscription(sub);
  if(!claim.ok)throw new Error(claim.error||'Could not register this device');
  toast('Push notifications enabled on this account.');
  render();
  return true;
 }catch(err){console.error(err);toast('Could not enable push notifications.');return false}
}
async function pushEnabled(){try{return !!(await getPushSubscription())}catch(_){return false}}
async function disablePushNotifications(){try{const sub=await getPushSubscription();if(sub){await sb.from('push_subscriptions').delete().eq('profile_id',session.user.id).eq('endpoint',sub.endpoint);await sub.unsubscribe();}toast('Push notifications disabled.');render()}catch(err){console.warn(err);toast('Could not disable push notifications.')}}
function pushSettingsMarkup(){
 const supported=('serviceWorker' in navigator)&&('PushManager' in window)&&('Notification' in window);
 if(!supported)return `<div class="push-setting"><div><b>Phone Push Notifications</b><small>This browser does not support web push.</small></div></div>`;
 return `<div class="push-setting"><div><b>Phone Push Notifications</b><small id="pushStatusText">Checking device permission…</small></div><div class="row" style="gap:8px;flex-wrap:wrap"><button class="btn" id="pushToggle">Enable</button><button class="btn" id="pushTest">Send Test Push</button></div></div>`;
}
async function refreshPushSetting(){const btn=document.getElementById('pushToggle'),txt=document.getElementById('pushStatusText');if(!btn)return;const sub=await pushEnabled();const perm=('Notification' in window)?Notification.permission:'default';if(sub){btn.textContent='Disable';btn.classList.add('danger');if(txt)txt.textContent='Enabled on this device.'}else{btn.textContent='Enable';btn.classList.remove('danger');if(txt)txt.textContent=perm==='denied'?'Blocked in browser settings.':'Get alerts even when the app is closed.'}}
function notificationReadKey(key){return `nolan-alert-read:${key}`}
function isSmartRead(key){try{return localStorage.getItem(notificationReadKey(key))==="1"}catch(_){return false}}
function markSmartRead(key){try{localStorage.setItem(notificationReadKey(key),"1")}catch(_){} }
function smartAlerts(){
 if(isFieldUser()) return [];
 const now=new Date(), jobs=state.jobs||[], invoices=state.invoices||[], payments=state.payments||[];
 const paidByInvoice={}; payments.forEach(p=>{if(p.invoice_id)paidByInvoice[p.invoice_id]=(paidByInvoice[p.invoice_id]||0)+Number(p.amount||0)});
 const out=[];
 (state.materials||[]).filter(m=>!['fulfilled','completed','complete','closed'].includes(String(m.status||'requested').toLowerCase())).slice(0,12).forEach(m=>{
  const j=jobs.find(x=>x.id===m.job_id); const key=`material:${m.id}`;
  out.push({smart:true,key,type:'material_request',title:'Material request needs attention',message:`${m.item||'Material'} · Qty ${m.quantity||1} · ${j?.name||'Job'}${m.requested_by?` · ${personName(m.requested_by)}`:''}`,job_id:m.job_id,created_at:m.created_at,action:{type:'attention',kind:'material',id:m.id},priority:'high'});
 });
 invoices.filter(i=>i.status!=='paid'&&i.due_date&&new Date(i.due_date)<now).slice(0,12).forEach(i=>{
  const j=jobs.find(x=>x.id===i.job_id); const remaining=Math.max(0,Number(i.total||0)-(paidByInvoice[i.id]||0)); const key=`invoice:${i.id}`;
  out.push({smart:true,key,type:'overdue_invoice',title:'Invoice is overdue',message:`${i.invoice_number||'Invoice'} · ${money(remaining)} outstanding · ${j?.name||'Job'} · Due ${dateFmt(i.due_date)}`,job_id:i.job_id,created_at:i.due_date,action:{type:'attention',kind:'invoice',id:i.id},priority:'high'});
 });
 (state.estimates||[]).filter(e=>['sent','draft'].includes(String(e.status||'').toLowerCase())&&e.created_at&&((now-new Date(e.created_at))/86400000)>=7).slice(0,12).forEach(e=>{
  const j=jobs.find(x=>x.id===e.job_id); const key=`estimate-followup:${e.id}`;
  out.push({smart:true,key,type:'estimate_followup',title:'Estimate may need follow-up',message:`${e.estimate_number||'Estimate'} · ${statusLabel(e.status)} · ${j?.name||'Job'} · ${dateFmt(e.created_at)}`,job_id:e.job_id,created_at:e.created_at,action:{type:'tab',tab:'estimates'},priority:'normal'});
 });
 const laborByJob={},costsByJob={}; (state.companyTimeEntries||[]).forEach(t=>{const rate=Number(state.employeeRates?.[t.profile_id]||0);laborByJob[t.job_id]=(laborByJob[t.job_id]||0)+(Number(t.duration_minutes||0)/60)*rate}); (state.companyJobCosts||[]).forEach(c=>{costsByJob[c.job_id]=(costsByJob[c.job_id]||0)+Number(c.amount||0)});
 jobs.forEach(j=>{const est=Number(j.estimated_labor_cost||0)+Number(j.estimated_material_cost||0)+Number(j.estimated_other_cost||0); const actual=(laborByJob[j.id]||0)+(costsByJob[j.id]||0); if(est>0&&actual>est*1.1){const key=`budget:${j.id}`; out.push({smart:true,key,type:'budget_risk',title:'Job is over budget',message:`${j.name} · ${money(actual)} actual vs ${money(est)} budget · ${((actual-est)/est*100).toFixed(0)}% over`,job_id:j.id,created_at:j.updated_at||j.created_at,action:{type:'job',id:j.id},priority:'high'});}});
 (state.reports||[]).filter(r=>r.created_at&&(now-new Date(r.created_at))/3600000<=24).slice(0,8).forEach(r=>{const key=`report:${r.id}`,j=jobs.find(x=>x.id===r.job_id);out.push({smart:true,key,type:'field_report',title:'New field report',message:`${j?.name||'Job'} · ${personName(r.submitted_by)} · ${Number(r.hours||0).toFixed(2)} hrs`,job_id:r.job_id,created_at:r.created_at,action:{type:'job',id:r.job_id},priority:'normal'});});
 return out.filter(n=>!isSmartRead(n.key));
}
