function toast(msg,type="info"){
 const stack=document.querySelector(".toast-stack")||(()=>{const x=document.createElement("div");x.className="toast-stack";x.setAttribute("aria-live","polite");x.setAttribute("aria-atomic","false");document.body.appendChild(x);return x})();
 const item=document.createElement("div");item.className=`toast toast-${type}`;item.setAttribute("role",type==="error"?"alert":"status");item.innerHTML=`<span class="toast-mark">${type==="error"?"!":type==="success"?"✓":"i"}</span><span class="toast-message">${esc(msg).replace(/\n/g,"<br>")}</span><button type="button" class="toast-close" aria-label="Dismiss notification">×</button>`;
 const close=()=>{item.classList.add("toast-leaving");setTimeout(()=>item.remove(),180)};item.querySelector(".toast-close").onclick=close;stack.appendChild(item);requestAnimationFrame(()=>item.classList.add("toast-visible"));setTimeout(close,5000);
}
function isFieldUser(){return profile?.role==="employee"||profile?.role==="crew_lead"}
function normalizeTab(){if(isFieldUser() && !["field","jobs"].includes(state.tab)) state.tab="field"; if(!isFieldUser() && state.tab==="field") state.tab="dashboard"}
function currentPage(){ return state.page || {type:"tab",tab:state.tab||"dashboard"}; }
function pageKey(page){return page?.type+":"+(page?.tab||page?.id||"")}
function navigate(page,{replace=false,fromPop=false}={}){
 document.querySelectorAll("body > .modal").forEach(m=>m.remove());
 const cur=currentPage();
 if(!replace && pageKey(cur)!==pageKey(page)) state.history.push(cur);
 state.page=page;
 state.tab=page.type==="tab"?page.tab:(page.type==="customer"?"customers":"jobs");
 state.selected=page.type==="job" ? state.jobs.find(j=>j.id===page.id)||null : null;
 const url="#"+(page.type==="tab"?page.tab:page.type+"/"+page.id);
 if(!fromPop){ if(replace) history.replaceState({nolanPage:page},"",url); else history.pushState({nolanPage:page},"",url); }
 render();
 load();
}
function goBack(){
 if(state.history.length){
  const prev=state.history.pop();
  navigate(prev,{replace:true});
  return;
 }
 navigate({type:"tab",tab:isFieldUser()?"field":"dashboard"},{replace:true});
}
function render(){
 normalizeTab();
 // IMPORTANT: render the application into one root container. Every navigation replaces
 // the previous page view; no page is ever appended underneath another page.
 root.replaceChildren();
 const shell=document.createElement("div");
 shell.innerHTML=session?appShell():login();
 while(shell.firstChild) root.appendChild(shell.firstChild);
 if(state.page?.type==="estimate") setTimeout(updateEstimateTotals,0);
 if(state.page?.type==="notifications") setTimeout(refreshPushSetting,0);
}
window.addEventListener("popstate",e=>{
 const p=e.state?.nolanPage;
 if(p){ state.page=p; state.tab=p.type==="tab"?p.tab:(p.type==="customer"?"customers":"jobs"); state.selected=p.type==="job"?state.jobs.find(j=>j.id===p.id)||null:null; render(); load(); }
});

