 const estPrint=e.target.closest('[data-estimate-print]');if(estPrint){const est=state.estimates.find(x=>x.id===estPrint.dataset.estimatePrint);const j=est&&state.jobs.find(x=>x.id===est.job_id);if(est&&j)printEstimate(est,j,state.estimateItems.filter(x=>x.estimate_id===est.id));return}
 if(e.target.id==='addEstimatePageLine'){const rows=document.getElementById('estimatePageRows');if(rows){const n=rows.querySelectorAll('.estimate-page-row').length;rows.insertAdjacentHTML('beforeend',estimateRow(n));updateEstimateTotals();}return}
 const remLine=e.target.closest('[data-remove-estimate-line]');if(remLine){const rows=document.querySelectorAll('.estimate-page-row');if(rows.length<=1){toast('Keep at least one line item.');return}remLine.closest('.estimate-page-row')?.remove();updateEstimateTotals();return}

