 if(e.target.id==='addEstimateLine'){const rows=e.target.closest('.sheet')?.querySelector('#estimateRows');if(rows){const n=rows.querySelectorAll('.estimate-edit-row').length;rows.insertAdjacentHTML('beforeend',`<div class="estimate-edit-row"><input name="desc_${n}" placeholder="Description"><input name="qty_${n}" type="number" step=".01" value="1"><input name="price_${n}" type="number" step=".01" value="0"><input name="cat_${n}" value="Electrical"></div>`)}return}
 if(e.target.id==='createEstimate'){if(state.selected&&!isFieldUser())estimateEditor(state.selected);return}
 if(e.target.id==='printEstimate'){const est=state.estimates.find(x=>x.job_id===state.selected?.id);if(est)printEstimate(est,state.selected,state.estimateItems.filter(x=>x.estimate_id===est.id));return}
 if(e.target.dataset.recordPayment){const inv=state.invoices.find(x=>x.id===e.target.dataset.recordPayment);if(inv)recordPayment(inv);return}
 if(e.target.id==='addReport'){if(state.selected)modalForm('Daily Job Report',`<form class="form"><input name="report_date" type="date" value="${new Date().toISOString().slice(0,10)}"><input name="hours" type="number" step=".25" placeholder="Hours worked"><textarea name="notes" required placeholder="What was completed today?
Crew on site:
Issues / blockers:
Materials needed:
Next steps:"></textarea><button class="btn primary" type="submit">Save Report</button></form>`,async f=>{const r=await sb.from('daily_reports').insert({job_id:state.selected.id,submitted_by:session.user.id,report_date:formValue(f,'report_date'),hours:Number(formValue(f,'hours')||0),notes:formValue(f,'notes')});if(!r.error)await logJobActivity(state.selected.id,'daily_report','Daily report added.');return r});return}
