let fieldActionSubmitting=false;
document.addEventListener("submit",async e=>{
 if(e.target.id!=="fieldActionForm") return;
 e.preventDefault();
 if(fieldActionSubmitting) return;
 fieldActionSubmitting=true;
 const form=e.target;
 const fd=new FormData(form);
 const getField=(name)=>fd.get(name);
 const page=currentPage();
 const action=page.action;
 const jobId=page.jobId||getField("job_id");
 if(!jobId){toast("Select a job first.");return}
 const job=state.jobs.find(j=>j.id===jobId);
 if(!job){toast("Job not found.");return}
 const button=form.querySelector(".action-submit");
 if(button){button.disabled=true;button.textContent="Saving..."}
 try{
  let r;
  if(action==="note") r=await sb.from("job_activity").insert({job_id:jobId,profile_id:session.user.id,event_type:"field_note",message:getField("message")});
  if(action==="material"){
   r=await sb.from("material_requests").insert({job_id:jobId,requested_by:session.user.id,item:getField("item"),quantity:Number(getField("quantity")||1),notes:getField("notes")});
   if(!r.error) await logJobActivity(jobId,"material_request",`Material requested: ${getField("item")}.`);
  }
  if(action==="report"){
   r=await sb.from("daily_reports").insert({job_id:jobId,submitted_by:session.user.id,report_date:getField("report_date"),hours:Number(getField("hours")||0),notes:getField("notes")});
   if(!r.error) await logJobActivity(jobId,"daily_report","Daily report added.");
  }
  if(action==="hours"){
   const hours=Number(getField("hours")||0),now=new Date().toISOString();
   r=await sb.from("time_entries").insert({job_id:jobId,profile_id:session.user.id,started_at:now,ended_at:now,duration_minutes:Math.round(hours*60),notes:getField("notes")});
   if(!r.error) await logJobActivity(jobId,"time_entry",`Logged ${hours.toFixed(2)} hours.`);
  }
  if(action==="photo"){
   const file=pendingPhotoFile||form.querySelector("#actionPhotoFile")?.files?.[0]||null;
   if(!file){toast("Take or choose a photo first.");if(button){button.disabled=false;button.textContent="Upload Photo"}return}
   const path=jobId+"/"+crypto.randomUUID()+"-"+file.name.replace(/[^a-zA-Z0-9._-]/g,"_");
   const up=await sb.storage.from("job-photos").upload(path,file,{upsert:false});
   if(up.error) throw new Error("Photo upload failed: "+up.error.message);
   r=await sb.from("job_photos").insert({job_id:jobId,uploaded_by:session.user.id,storage_path:path,caption:getField("caption")||null});
   if(!r.error) await logJobActivity(jobId,"photo_added",`Job photo added${getField("caption")?`: ${getField("caption")}`:"."}`);
  }
  if(r?.error) throw r.error;
  state.selected=job;
  await load();
  navigate({type:"job",id:jobId},{replace:true});
  if(action==="photo"){if(pendingPhotoPreviewUrl){try{URL.revokeObjectURL(pendingPhotoPreviewUrl)}catch(_){} }pendingPhotoFile=null;pendingPhotoPreviewUrl=null;}
  toast(action==="photo"?"Photo uploaded.":"Saved successfully.");
  fieldActionSubmitting=false;
 }catch(err){console.error(err);toast(err?.message||"Could not save. Please try again.");if(button){button.disabled=false;button.textContent=action==="photo"?"Upload Photo":action==="material"?"Request Material":action==="report"?"Save Daily Report":action==="hours"?"Save Hours":"Save Note"} fieldActionSubmitting=false}
});

document.addEventListener("change",e=>{
 if(e.target.id==="actionPhotoFile"){
  const file=e.target.files?.[0];
  if(pendingPhotoPreviewUrl){try{URL.revokeObjectURL(pendingPhotoPreviewUrl)}catch(_){} }
  pendingPhotoFile=file||null;
  pendingPhotoPreviewUrl=file?URL.createObjectURL(file):null;
  const preview=document.getElementById("photoPreview");
  if(!preview)return;
  preview.innerHTML=file?`<img src="${esc(pendingPhotoPreviewUrl)}" alt="Selected job photo"><span>✓ Photo ready to upload · ${esc(file.name||"Camera photo")}</span>`:"<span>No photo selected</span>";
 }
});

let timerTicker=null;
function startTimerTicker(){
 if(timerTicker) clearInterval(timerTicker);
 const tick=()=>{document.querySelectorAll("[data-timer-start]").forEach(el=>{const start=new Date(el.dataset.timerStart);const sec=Math.max(0,Math.floor((Date.now()-start)/1000));const h=Math.floor(sec/3600),m=Math.floor((sec%3600)/60),ss=sec%60;el.textContent=`Running · ${h}h ${String(m).padStart(2,"0")}m ${String(ss).padStart(2,"0")}s`;});};
 tick(); timerTicker=setInterval(tick,1000);
}
startTimerTicker();
let notificationTicker=null;
function startNotificationTicker(){
 if(notificationTicker)clearInterval(notificationTicker);
 notificationTicker=setInterval
function openSchedulePicker(existing=null){
 if(!existing){const candidates=state.jobs.filter(j=>!j.scheduled_start&&["approved","scheduled","in_progress","punch_list"].includes(j.status));if(!candidates.length){toast("No approved or active jobs need scheduling.");return}}
 const j=existing||null;
 const defaultDate=j?.scheduled_start||new Date().toISOString();
 const start=scheduleLocalInput(defaultDate,8);let end=scheduleLocalInput(j?.scheduled_end,16);if(!j?.scheduled_end){const d=new Date(start);d.setHours(d.getHours()+Math.max(1,Math.min(10,Number(j?.estimated_labor_hours||8))));end=scheduleLocalInput(d.toISOString());}
 const jobs=state.jobs.filter(x=>!x.scheduled_start||x.id===j?.id).filter(x=>["approved","scheduled","in_progress","punch_list"].includes(x.status));
 modalForm(j?"Reschedule Job":"Schedule a Job",`<form class="form"><label>Job<select name="job_id" required>${jobs.map(x=>`<option value="${x.id}" ${x.id===j?.id?'selected':''}>${esc(x.job_number||'')} · ${esc(x.name)} · ${esc(x.customers?.name||'Customer')}</option>`).join("")}</select></label><label>Start<input name="scheduled_start" type="datetime-local" value="${start}" required></label><label>End<input name="scheduled_end" type="datetime-local" value="${end}" required></label><select name="status"><option value="scheduled">Scheduled</option><option value="in_progress">In Progress</option><option value="approved">Approved</option><option value="punch_list">Punch List</option></select><div class="sub">Crew members already assigned to the job will be checked for overlapping jobs.</div><button class="btn primary" type="submit">Save Schedule</button></form>`,async f=>{const job=state.jobs.find(x=>x.id===formValue(f,"job_id"));if(!job)return {error:{message:"Choose a job."}};const s=new Date(formValue(f,"scheduled_start")),en=new Date(formValue(f,"scheduled_end"));if(!(s<en))return {error:{message:"End time must be after start time."}};const conflicts=scheduleConflicts(job,s.toISOString(),en.toISOString(),job.id);if(conflicts.length)return {error:{message:`Crew conflict: ${conflicts.map(x=>x.name).join(", ")} overlaps this time.`}};return sb.from("jobs").update({scheduled_start:s.toISOString(),scheduled_end:en.toISOString(),status:formValue(f,"status")||"scheduled"}).eq("id",job.id)});
}
document.addEventListener("dragstart",e=>{const card=e.target.closest("[data-schedule-drag]");if(card){e.dataTransfer.setData("text/plain",card.dataset.scheduleDrag);e.dataTransfer.effectAllowed="move";card.classList.add("dragging");}});
document.addEventListener("dragend",e=>{const card=e.target.closest("[data-schedule-drag]");if(card)card.classList.remove("dragging");});
document.addEventListener("dragover",e=>{const zone=e.target.closest("[data-schedule-day]");if(zone){e.preventDefault();zone.classList.add("drag-over");}});
document.addEventListener("dragleave",e=>{const zone=e.target.closest("[data-schedule-day]");if(zone)zone.classList.remove("drag-over");});
document.addEventListener("drop",async e=>{const zone=e.target.closest("[data-schedule-day]");if(!zone)return;e.preventDefault();zone.classList.remove("drag-over");const id=e.dataTransfer.getData("text/plain"),job=state.jobs.find(x=>x.id===id);if(!job)return;const day=zone.dataset.scheduleDay;const old=job.scheduled_start?new Date(job.scheduled_start):new Date();const start=new Date(`${day}T${String(old.getHours()).padStart(2,"0")}:${String(old.getMinutes()).padStart(2,"0")}:00`);if(!job.scheduled_start)start.setHours(8,0,0,0);const hours=scheduledHours(job)||Math.max(1,Math.min(10,Number(job.estimated_labor_hours||8)));const end=new Date(start.getTime()+hours*3600000);const conflicts=scheduleConflicts(job,start.toISOString(),end.toISOString(),job.id);if(conflicts.length){toast(`Crew conflict: ${conflicts.map(x=>x.name).join(", ")} overlaps this time.`);return}const r=await sb.from("jobs").update({scheduled_start:start.toISOString(),scheduled_end:end.toISOString(),status:job.status==="approved"?"scheduled":job.status}).eq("id",job.id);if(r.error)toast(r.error.message);else{toast("Job moved on the schedule.");await load();}});

(async()=>{if(!session||!sb)return;try{const r=await sb.from("notifications").select("*").order("created_at",{ascending:false}).limit(100);if(!r.error){state.notifications=r.data||[];if(currentPage().type==="notifications"){render();setTimeout(refreshPushSetting,0);}else{const bell=document.getElementById("openNotifications");if(bell){const count=notificationCount();bell.innerHTML=`<span>🔔</span>${count?`<b>${count>99?"99+":count}</b>`:""}`;}}}}catch(_){}},60000);
}
startNotificationTicker();

document.addEventListener("keydown",e=>{if(e.target.id==="customerSearch"&&e.key==="Enter"){e.preventDefault();state.customerSearch=e.target.value;render();}});

document.addEventListener("change",async e=>{
 const ms=e.target.dataset.materialStatus;if(ms){const r=await sb.from('material_requests').update({status:e.target.value}).eq('id',ms);if(r.error)toast(r.error.message);else await load();return}

 const id=e.target.dataset.task;if(id){const checked=e.target.checked;const r=await sb.from("job_tasks").update({status:checked?"complete":"open",completed_at:checked?new Date().toISOString():null}).eq("id",id);if(r.error)toast(r.error.message);else{const t=state.tasks.find(x=>x.id===id);await logJobActivity(state.selected?.id,"task_update",`${checked?"Completed":"Reopened"} task: ${t?.title||"Task"}.`);}await load();return}
 const taskId=e.target.dataset.taskAssignee;if(taskId){const assigned=e.target.value||null;const task=state.tasks.find(x=>x.id===taskId);const r=await sb.from("job_tasks").update({assigned_to:assigned}).eq("id",taskId);if(r.error)toast(r.error.message);else{if(assigned)await notifyProfile(assigned,state.selected?.id,"task_assigned","Task assigned to you",`${task?.title||"Task"} · ${state.selected?.name||"Job"}`);await load()}}
});

document.addEventListener("input",e=>{
 if(e.target.closest("#estimatePageForm") && (e.target.name||"").match(/^(qty_|price_|tax$)/)){updateEstimateTotals();}
 if(e.target.id==="customerSearch"){state.customerSearch=e.target.value; const box=document.querySelector(".customer-grid"); if(box) box.innerHTML=customerGridMarkup();}
});

document.addEventListener("click",e=>{
 if(e.target.id==="backButton"){goBack();return;}
});

document.addEventListener("submit",async e=>{
 if(e.target.id==="estimatePageForm"){
  e.preventDefault(); if(isFieldUser())return;
  const form=e.target,fd=new FormData(form),page=currentPage();
  const jobId=fd.get('job_id')||page.jobId||null;
  if(!jobId){toast('Select a job first.');return;}
  const rows=[...form.querySelectorAll('.estimate-page-row')].map(r=>({description:String(r.querySelector('[name^="desc_"]')?.value||'').trim(),quantity:Number(r.querySelector('[name^="qty_"]')?.value||0),sell_price:Number(r.querySelector('[name^="price_"]')?.value||0),category:String(r.querySelector('[name^="cat_"]')?.value||'Electrical').trim()})).filter(x=>x.description&&x.quantity>0);
  if(!rows.length){toast('Add at least one line item.');return;}
  const existing=state.estimates.find(x=>x.id===page.id); const tax=Number(fd.get('tax')||0); const subtotal=rows.reduce((a,x)=>a+x.quantity*x.sell_price,0); const total=subtotal+tax;
  const payload={job_id:jobId,estimate_number:String(fd.get('estimate_number')||''),status:String(fd.get('status')||'draft'),subtotal,tax,total,notes:`TERMS & CONDITIONS:\n${String(fd.get('terms')||'').trim()}\n\nEXCLUSIONS:\n${String(fd.get('exclusions')||'').trim()}`.trim(),updated_at:new Date().toISOString()};
  const button=form.querySelectorAll('button[type="submit"]');button.forEach(b=>{b.disabled=true;b.textContent='Saving...'});
  try{
   let r=existing?await sb.from('estimates').update(payload).eq('id',existing.id).select().single():await sb.from('estimates').insert(payload).select().single();
   if(r.error)throw r.error; const eid=existing?.id||r.data.id;
   const dr=await sb.from('estimate_items').delete().eq('estimate_id',eid); if(dr.error)throw dr.error;
   const ir=await sb.from('estimate_items').insert(rows.map(x=>({...x,estimate_id:eid,unit_cost:0}))); if(ir.error)throw ir.error;
   if(payload.status==='approved') await sb.from('jobs').update({contract_amount:total,status:'approved'}).eq('id',jobId);
   state.estimates=[...(state.estimates||[])].filter(x=>x.id!==eid);state.estimates.push({...payload,id:eid});
   toast('Estimate saved.');navigate({type:'tab',tab:'estimates'});
  }catch(err){console.error(err);toast(err?.message||'Could not save estimate.');button.forEach(b=>{b.disabled=false;b.textContent='Save Estimate'});}
  return;
 }
 if(e.target.id==="login"){e.preventDefault();const {error}=await sb.auth.signInWithPassword({email:e.target.email.value,password:e.target.pw.value});if(error)toast(error.message)}
});

function updateEstimateTotals(){
 const form=document.getElementById('estimatePageForm');if(!form)return;
 const subtotal=[...form.querySelectorAll('.estimate-page-row')].reduce((a,r)=>a+Number(r.querySelector('[name^="qty_"]')?.value||0)*Number(r.querySelector('[name^="price_"]')?.value||0),0);
 const tax=Number(form.querySelector('[name="tax"]')?.value||0),total=subtotal+tax;
 const a=document.getElementById('estimateLiveSubtotal'),b=document.getElementById('estimateLiveTax'),c=document.getElementById('estimateLiveTotal');if(a)a.textContent=money(subtotal);if(b)b.textContent=money(tax);if(c)c.textContent=money(total);
}

function estimateEditor(j){
 const existing=state.estimates.find(x=>x.job_id===j.id); const items=existing?state.estimateItems.filter(x=>x.estimate_id===existing.id):[]; const next='EST-'+new Date().getFullYear()+'-'+String(state.estimates.length+1).padStart(3,'0');
 modalForm(existing?'Edit Estimate':'Build Estimate',`<form class="form"><input name="estimate_number" value="${esc(existing?.estimate_number||next)}" required><select name="status"><option value="draft" ${!existing||existing.status==='draft'?'selected':''}>Draft</option><option value="sent" ${existing?.status==='sent'?'selected':''}>Sent</option><option value="approved" ${existing?.status==='approved'?'selected':''}>Approved</option><option value="rejected" ${existing?.status==='rejected'?'selected':''}>Rejected</option></select><div id="estimateRows">${items.map((it,i)=>`<div class="estimate-edit-row"><input name="desc_${i}" value="${esc(it.description)}" placeholder="Description" required><input name="qty_${i}" type="number" step=".01" value="${it.quantity}"><input name="price_${i}" type="number" step=".01" value="${it.sell_price}"><input name="cat_${i}" value="${esc(it.category||'General')}"></div>`).join('')||`<div class="estimate-edit-row"><input name="desc_0" placeholder="Description" required><input name="qty_0" type="number" step=".01" value="1"><input name="price_0" type="number" step=".01" value="${Number(j.contract_amount||0)}"><input name="cat_0" value="Electrical"></div>`}</div><button type="button" class="btn" id="addEstimateLine">+ Line Item</button><input name="tax" type="number" step=".01" value="${existing?.tax||0}" placeholder="Tax"><textarea name="notes" placeholder="Estimate notes / terms">${esc(existing?.notes||'')}</textarea><button class="btn primary" type="submit">Save Estimate</button></form>`,async f=>{let r;if(existing)r=await sb.from('estimates').update({estimate_number:formValue(f,'estimate_number'),status:formValue(f,'status'),tax:Number(formValue(f,'tax')||0),notes:formValue(f,'notes')||'',updated_at:new Date().toISOString()}).eq('id',existing.id).select().single();else r=await sb.from('estimates').insert({job_id:j.id,estimate_number:formValue(f,'estimate_number'),status:formValue(f,'status'),subtotal:0,tax:Number(formValue(f,'tax')||0),total:0,notes:formValue(f,'notes')||''}).select().single();if(r.error)return r;const eid=existing?.id||r.data.id;if(existing){const dr=await sb.from('estimate_items').delete().eq('estimate_id',eid);if(dr.error)return dr;}const entries=Object.keys(Object.fromEntries(f.entries())).map(k=>{const m=k.match(/^desc_(\d+)$/);return m&&m[1]}).filter(Boolean);const rows=entries.map(i=>({estimate_id:eid,description:String(formValue(f,'desc_'+i)||''),quantity:Number(formValue(f,'qty_'+i)||0),sell_price:Number(formValue(f,'price_'+i)||0),unit_cost:0,category:String(formValue(f,'cat_'+i)||'General')})).filter(x=>x.description&&x.quantity>0);if(rows.length){const ir=await sb.from('estimate_items').insert(rows);if(ir.error)return ir;}const subtotal=rows.reduce((a,x)=>a+x.quantity*x.sell_price,0),tax=Number(formValue(f,'tax')||0);return sb.from('estimates').update({subtotal,total:subtotal+tax,updated_at:new Date().toISOString()}).eq('id',eid)});
}
function recordPayment(inv){modalForm('Record Payment',`<form class="form"><p class="sub">Invoice ${esc(inv.invoice_number)} · ${money(inv.total)}</p><input name="amount" type="number" min=".01" step=".01" value="${inv.total}" required><input name="payment_date" type="date" value="${new Date().toISOString().slice(0,10)}"><select name="method"><option>Check</option><option>ACH</option><option>Card</option><option>Cash</option><option>Other</option></select><input name="reference" placeholder="Check # / confirmation"><textarea name="notes" placeholder="Notes"></textarea><button class="btn primary" type="submit">Record Payment</button></form>`,async f=>{const r=await sb.from('payments').insert({invoice_id:inv.id,amount:Number(formValue(f,'amount')||0),payment_date:formValue(f,'payment_date'),method:formValue(f,'method'),reference:formValue(f,'reference'),notes:formValue(f,'notes')});if(r.error)return r;const all=await sb.from('payments').select('amount').eq('invoice_id',inv.id);const sum=(all.data||[]).reduce((a,x)=>a+Number(x.amount||0),0);const status=sum>=Number(inv.total||0)?'paid':'sent';return sb.from('invoices').update({status,paid_at:status==='paid'?new Date().toISOString():null}).eq('id',inv.id)})}
async function logJobActivity(jobId,event_type,message){try{await sb.from("job_activity").insert({job_id:jobId,profile_id:session.user.id,event_type,message});}catch(_){}}

function estimateStatusClass(status){return String(status||'draft').toLowerCase().replace(/[^a-z0-9_-]/g,'-')}
function estimates(){
 if(isFieldUser()) return `<div class="card"><h2>Estimates</h2><p class="sub">Estimates are managed by the office.</p></div>`;
 const list=[...(state.estimates||[])].sort((a,b)=>new Date(b.updated_at||b.created_at||0)-new Date(a.updated_at||a.created_at||0));
 const total=list.reduce((a,e)=>a+Number(e.total||0),0);
 return `<div class="page-heading"><div><div class="eyebrow">ESTIMATING</div><h1>Estimates</h1><p>Build, price, revise and print customer estimates.</p></div><button class="btn primary big-action" id="newEstimatePage">+ New Estimate</button></div>
 <div class="metric-grid"><div class="card metric-v2"><span>Total Estimates</span><b>${list.length}</b><small>All estimate records</small></div><div class="card metric-v2"><span>Drafts</span><b>${list.filter(e=>e.status==='draft').length}</b><small>Still being built</small></div><div class="card metric-v2"><span>Approved</span><b>${list.filter(e=>e.status==='approved').length}</b><small>Ready to move forward</small></div><div class="card metric-v2"><span>Estimated Sales</span><b>${money(total)}</b><small>Total estimate value</small></div></div>
 <section class="card"><div class="section-head"><div><div class="eyebrow">ESTIMATE PIPELINE</div><h2>All Estimates</h2></div></div><div class="estimate-list">${list.map(e=>{const j=state.jobs.find(x=>x.id===e.job_id);const c=j?.customers;return `<div class="estimate-card"><div class="estimate-card-main"><div class="eyebrow">${esc(e.estimate_number||'ESTIMATE')}</div><h3>${esc(j?.name||'Job')}</h3><p>${esc(c?.name||'Customer')}${c?.company?` · ${esc(c.company)}`:''}</p><div class="sub">Updated ${dateTimeFmt(e.updated_at||e.created_at)}</div></div><div class="estimate-card-side"><span class="status-chip status-${estimateStatusClass(e.status)}">${statusLabel(e.status)}</span><b>${money(e.total)}</b><button class="btn" data-estimate-open="${e.id}">Open</button><button class="btn" data-estimate-print="${e.id}">Document</button></div></div>`}).join('')||`<div class="empty">No estimates yet. Start one from a job or create a new estimate.</div>`}</div></section>`;
}
function estimateEditorPage(page){
 if(isFieldUser()) return `<div class="card"><h2>Estimates</h2><p class="sub">Office-only.</p></div>`;
 const existing=state.estimates.find(x=>x.id===page.id);
 const jobs=state.jobs.filter(j=>!['closed'].includes(j.status));
 const job=existing?state.jobs.find(j=>j.id===existing.job_id):(page.jobId?state.jobs.find(j=>j.id===page.jobId):null);
 const items=existing?state.estimateItems.filter(x=>x.estimate_id===existing.id):[];
 const next='EST-'+new Date().getFullYear()+'-'+String((state.estimates||[]).length+1).padStart(3,'0');
 const rows=items.length?items.map((it,i)=>estimateRow(i,it)).join(''):estimateRow(0,{description:'',quantity:1,sell_price:0,category:'Electrical'});
 return `<div class="estimate-editor-page"><div class="page-back"><button class="btn" id="backButton">← Back to Estimates</button></div>
 <div class="page-heading"><div><div class="eyebrow">${existing?'EDIT ESTIMATE':'NEW ESTIMATE'}</div><h1>${existing?'Edit Estimate':'Build Estimate'}</h1><p>${job?esc(job.name)+' · '+esc(job.customers?.name||'Customer'):'Choose a job, then build the customer-facing price.'}</p></div><div class="estimate-editor-actions">${existing?`<button class="btn" id="printEstimatePage">Print Estimate</button>`:''}<button class="btn primary" form="estimatePageForm">Save Estimate</button></div></div>
 <form id="estimatePageForm" class="estimate-page-form"><section class="card"><div class="eyebrow">ESTIMATE DETAILS</div><div class="form-grid-2"><label>Job<select name="job_id" required ${existing?'disabled':''}><option value="">Select job…</option>${jobs.map(j=>`<option value="${j.id}" ${(job?.id===j.id)?'selected':''}>${esc(j.name)} — ${esc(j.customers?.name||'Customer')}</option>`).join('')}</select></label><label>Estimate Number<input name="estimate_number" value="${esc(existing?.estimate_number||next)}" required></label><label>Status<select name="status"><option value="draft" ${!existing||existing.status==='draft'?'selected':''}>Draft</option><option value="sent" ${existing?.status==='sent'?'selected':''}>Sent</option><option value="approved" ${existing?.status==='approved'?'selected':''}>Approved</option><option value="rejected" ${existing?.status==='rejected'?'selected':''}>Rejected</option></select></label><label>Tax<input name="tax" type="number" min="0" step="0.01" value="${Number(existing?.tax||0)}" placeholder="0.00"></label></div></section>
 <section class="card"><div class="section-head"><div><div class="eyebrow">CUSTOMER PRICING</div><h2>Line Items</h2><p class="sub">Price the work exactly how you want the customer to see it.</p></div><button type="button" class="btn" id="addEstimatePageLine">+ Add Line</button></div><div class="estimate-line-head"><span>Description</span><span>Qty</span><span>Unit Price</span><span>Category</span><span></span></div><div id="estimatePageRows">${rows}</div><div class="estimate-totals-box"><div><span>Subtotal</span><b id="estimateLiveSubtotal">$0.00</b></div><div><span>Tax</span><b id="estimateLiveTax">$0.00</b></div><div class="grand"><span>Customer Total</span><b id="estimateLiveTotal">$0.00</b></div></div></section>
 <section class="card"><div class="eyebrow">CUSTOMER DOCUMENT</div><div class="form-grid-2"><label>Terms & Conditions<textarea name="terms" rows="7" placeholder="Payment terms, warranty, scheduling, change-order terms…">${esc((String(existing?.notes||'').match(/(?:^|\n)\s*TERMS\s*(?:&|AND)?\s*(?:CONDITIONS)?\s*:\s*([\s\S]*?)(?=\n\s*EXCLUSIONS\s*:|$)/i)||[])[1]||existing?.notes||'')}</textarea></label><label>Exclusions<textarea name="exclusions" rows="7" placeholder="Permits, engineering, utility fees, concealed conditions, owner-supplied items…">${esc((String(existing?.notes||'').match(/(?:^|\n)\s*EXCLUSIONS\s*:\s*([\s\S]*)$/i)||[])[1]||'')}</textarea></label></div><p class="sub">These sections appear on the customer-facing proposal. Internal costs and markup are never shown.</p></section>
 <div class="estimate-bottom-save"><button class="btn" type="button" id="backButton2">Cancel</button><button class="btn primary" type="submit">Save Estimate</button></div></form></div>`;
}
function estimateRow(i,it={}){return `<div class="estimate-page-row"><input name="desc_${i}" value="${esc(it.description||'')}" placeholder="Electrical work / material" required><input name="qty_${i}" type="number" min="0.01" step="0.01" value="${Number(it.quantity||1)}"><input name="price_${i}" type="number" min="0" step="0.01" value="${Number(it.sell_price||0)}"><input name="cat_${i}" value="${esc(it.category||'Electrical')}" placeholder="Electrical"><button type="button" class="btn danger estimate-remove-line" data-remove-estimate-line="1">Remove</button></div>`}

function customerGridMarkup(){
 const q=state.customerSearch.trim().toLowerCase();
 const list=state.customers.filter(c=>!q||[c.name,c.company,c.phone,c.email].some(v=>String(v||'').toLowerCase().includes(q)));
 return list.map(c=>{const props=state.properties.filter(p=>p.customer_id===c.id);const jobs=state.jobs.filter(j=>j.customer_id===c.id);return `<div class="customer-card" data-customer="${c.id}"><div class="row"><div><b>${esc(c.name)}</b><div class="sub">${esc(c.company||'Individual')}</div></div><span class="avatar small">${esc((c.name||'?').slice(0,1).toUpperCase())}</span></div><div class="customer-contact">${c.phone?`<span>☎ ${esc(c.phone)}</span>`:''}${c.email?`<span>✉ ${esc(c.email)}</span>`:''}</div><div class="customer-summary"><span><b>${props.length}</b> ${props.length===1?'property':'properties'}</span><span><b>${jobs.length}</b> ${jobs.length===1?'job':'jobs'}</span></div></div>`}).join('')||`<div class="empty">No customers match your search.</div>`;
}
function customerPage(c){
 if(!c) return `<div class="card"><button class="btn" id="backButton">← Back</button><h2>Customer not found</h2></div>`;
 const jobs=state.jobs.filter(j=>j.customer_id===c.id).sort((a,b)=>new Date(b.created_at||0)-new Date(a.created_at||0));
 const props=state.properties.filter(p=>p.customer_id===c.id);
 const propAddress=p=>[p.address_line1,p.city,p.state,p.postal_code].filter(Boolean).join(', ');
 const contract=jobs.reduce((a,j)=>a+Number(j.contract_amount||0),0);
 const inv=state.invoices.filter(i=>jobs.some(j=>j.id===i.job_id));
 const invoiced=inv.reduce((a,i)=>a+Number(i.total||0),0);
 const pays=state.payments.filter(p=>inv.some(i=>i.id===p.invoice_id));
 const paid=pays.reduce((a,p)=>a+Number(p.amount||0),0);
 return `<div class="customer-page">
  <div class="page-back"><button class="btn" id="backButton">← Customers</button></div>
  <section class="card customer-account-hero"><div class="customer-account-main"><div class="avatar">${esc((c.name||'?').slice(0,1).toUpperCase())}</div><div><div class="eyebrow">CUSTOMER ACCOUNT</div><h1>${esc(c.name)}</h1><p>${esc(c.company||'Individual')} ${c.phone?` · ${esc(c.phone)}`:''} ${c.email?` · ${esc(c.email)}`:''}</p></div></div><div class="customer-account-actions"><button class="btn" id="editCustomerPage">Edit Customer</button><button class="btn" id="addPropertyPage">+ Property</button><button class="btn primary" id="newJobForCustomer">+ New Job</button></div></section>
  <div class="customer360-stats"><div><span>Contract Value</span><b>${money(contract)}</b></div><div><span>Invoiced</span><b>${money(invoiced)}</b></div><div><span>Payments</span><b>${money(paid)}</b></div><div><span>Balance</span><b>${money(Math.max(0,invoiced-paid))}</b></div></div>
  <div class="customer360-grid"><section class="card"><div class="section-head"><div><div class="eyebrow">JOB SITES</div><h2>Properties</h2></div></div>${props.map(p=>`<div class="job"><b>${esc(propAddress(p))}</b><div class="sub">${jobs.filter(j=>j.property_id===p.id).length} job${jobs.filter(j=>j.property_id===p.id).length===1?'':'s'}</div></div>`).join('')||'<div class="empty">No properties yet.</div>'}</section>
  <section class="card"><div class="section-head"><div><div class="eyebrow">WORK HISTORY</div><h2>Jobs</h2></div><span class="sub">${jobs.length} total</span></div>${jobs.map(j=>`<button class="job customer-job-link" data-job="${j.id}"><div class="row"><div><b>${esc(j.job_number)} · ${esc(j.name)}</b><div class="sub">${statusLabel(j.status)} · ${j.property_id&&props.find(p=>p.id===j.property_id)?esc(propAddress(props.find(p=>p.id===j.property_id))):'No property assigned'}</div></div><b>${money(j.contract_amount)}</b></div></button>`).join('')||'<div class="empty">No jobs yet.</div>'}</section></div>
  <section class="card customer-history"><div class="eyebrow">ACCOUNT HISTORY</div><h2>Estimates, Invoices & Payments</h2>${inv.map(i=>`<div class="history-list"><div><b>${esc(i.invoice_number||'Invoice')}</b><small>${statusLabel(i.status)} · ${dateFmt(i.due_date)}</small></div><b>${money(i.total)}</b><span>${money(pays.filter(p=>p.invoice_id===i.id).reduce((a,p)=>a+Number(p.amount||0),0))} paid</span></div>`).join('')||'<div class="empty">No invoices yet.</div>'}</section>
  <section class="card customer-history"><div class="eyebrow">NOTES</div><p>${esc(c.notes||'No customer notes.')}</p></section>
 </div>`;
}
function propertyForm(c){modalForm('Add Property',`<form class="form"><p class="sub">Property for ${esc(c.name)}</p><input name="address_line1" placeholder="Street address" required><input name="city" placeholder="City"><input name="state" placeholder="State" value="GA"><input name="postal_code" placeholder="ZIP"><button class="btn primary" type="submit">Save Property</button></form>`,f=>sb.from('properties').insert({customer_id:c.id,address_line1:formValue(f,'address_line1'),city:formValue(f,'city'),state:formValue(f,'state'),postal_code:formValue(f,'postal_code')}));}


function openSchedulePicker(existing=null){
 if(!existing){const candidates=state.jobs.filter(j=>!j.scheduled_start&&["approved","scheduled","in_progress","punch_list"].includes(j.status));if(!candidates.length){toast("No approved or active jobs need scheduling.");return}}
 const j=existing||null;
 const defaultDate=j?.scheduled_start||new Date().toISOString();
 const start=scheduleLocalInput(defaultDate,8);let end=scheduleLocalInput(j?.scheduled_end,16);if(!j?.scheduled_end){const d=new Date(start);d.setHours(d.getHours()+Math.max(1,Math.min(10,Number(j?.estimated_labor_hours||8))));end=scheduleLocalInput(d.toISOString());}
 const jobs=state.jobs.filter(x=>!x.scheduled_start||x.id===j?.id).filter(x=>["approved","scheduled","in_progress","punch_list"].includes(x.status));
 modalForm(j?"Reschedule Job":"Schedule a Job",`<form class="form"><label>Job<select name="job_id" required>${jobs.map(x=>`<option value="${x.id}" ${x.id===j?.id?'selected':''}>${esc(x.job_number||'')} · ${esc(x.name)} · ${esc(x.customers?.name||'Customer')}</option>`).join("")}</select></label><label>Start<input name="scheduled_start" type="datetime-local" value="${start}" required></label><label>End<input name="scheduled_end" type="datetime-local" value="${end}" required></label><select name="status"><option value="scheduled">Scheduled</option><option value="in_progress">In Progress</option><option value="approved">Approved</option><option value="punch_list">Punch List</option></select><div class="sub">Crew members already assigned to the job will be checked for overlapping jobs.</div><button class="btn primary" type="submit">Save Schedule</button></form>`,async f=>{const job=state.jobs.find(x=>x.id===formValue(f,"job_id"));if(!job)return {error:{message:"Choose a job."}};const s=new Date(formValue(f,"scheduled_start")),en=new Date(formValue(f,"scheduled_end"));if(!(s<en))return {error:{message:"End time must be after start time."}};const conflicts=scheduleConflicts(job,s.toISOString(),en.toISOString(),job.id);if(conflicts.length)return {error:{message:`Crew conflict: ${conflicts.map(x=>x.name).join(", ")} overlaps this time.`}};return sb.from("jobs").update({scheduled_start:s.toISOString(),scheduled_end:en.toISOString(),status:formValue(f,"status")||"scheduled"}).eq("id",job.id)});
}
document.addEventListener("dragstart",e=>{const card=e.target.closest("[data-schedule-drag]");if(card){e.dataTransfer.setData("text/plain",card.dataset.scheduleDrag);e.dataTransfer.effectAllowed="move";card.classList.add("dragging");}});
document.addEventListener("dragend",e=>{const card=e.target.closest("[data-schedule-drag]");if(card)card.classList.remove("dragging");});
document.addEventListener("dragover",e=>{const zone=e.target.closest("[data-schedule-day]");if(zone){e.preventDefault();zone.classList.add("drag-over");}});
document.addEventListener("dragleave",e=>{const zone=e.target.closest("[data-schedule-day]");if(zone)zone.classList.remove("drag-over");});
document.addEventListener("drop",async e=>{const zone=e.target.closest("[data-schedule-day]");if(!zone)return;e.preventDefault();zone.classList.remove("drag-over");const id=e.dataTransfer.getData("text/plain"),job=state.jobs.find(x=>x.id===id);if(!job)return;const day=zone.dataset.scheduleDay;const old=job.scheduled_start?new Date(job.scheduled_start):new Date();const start=new Date(`${day}T${String(old.getHours()).padStart(2,"0")}:${String(old.getMinutes()).padStart(2,"0")}:00`);if(!job.scheduled_start)start.setHours(8,0,0,0);const hours=scheduledHours(job)||Math.max(1,Math.min(10,Number(job.estimated_labor_hours||8)));const end=new Date(start.getTime()+hours*3600000);const conflicts=scheduleConflicts(job,start.toISOString(),end.toISOString(),job.id);if(conflicts.length){toast(`Crew conflict: ${conflicts.map(x=>x.name).join(", ")} overlaps this time.`);return}const r=await sb.from("jobs").update({scheduled_start:start.toISOString(),scheduled_end:end.toISOString(),status:job.status==="approved"?"scheduled":job.status}).eq("id",job.id);if(r.error)toast(r.error.message);else{toast("Job moved on the schedule.");await load();}});

(async()=>{
 try{
  if(!createClient){fatalBoot("Supabase library did not load.","The Supabase CDN script could not be loaded.");return}
  if(!cfg.supabaseUrl || !cfg.supabaseKey || String(cfg.supabaseKey).includes("PASTE_")){fatalBoot("Supabase configuration is missing.","Keep your existing config.js in the GitHub repository. V59 does not replace or include your private configuration file.");return}
  sb=createClient(cfg.supabaseUrl,cfg.supabaseKey);
 const {data}=await sb.auth.getSession();session=data.session;
 if(session){const {data:p}=await sb.from("profiles").select("*").eq("id",session.user.id).maybeSingle();profile=p;normalizeTab()}
 if(!history.state?.nolanPage) history.replaceState({nolanPage:state.page},"",location.hash||"#"+state.page.tab);
  render();if(session){load();registerPushServiceWorker().then(reg=>reg&&claimPushSubscription());}
  sb.auth.onAuthStateChange(async(_e,s)=>{session=s;if(s){const {data:p}=await sb.from("profiles").select("*").eq("id",s.user.id).maybeSingle();profile=p;normalizeTab()}else{profile=null;state.tab="dashboard"}render();if(s){load();registerPushServiceWorker().then(reg=>reg&&claimPushSubscription());}});
 }catch(err){fatalBoot("The app hit an unexpected startup error.",err?.message||String(err));}
})();